<template>
  <div class="page">
    <div class="crumb"><button @click="router.back()">课程作业</button><span>›</span><strong>{{ detail?.title || '作业详情' }}</strong></div>
    <div v-if="errorMessage" class="error">{{ errorMessage }}</div>
    <section v-if="detail" class="panel">
      <header><div><p>ASSIGNMENT DETAIL</p><h1>{{ detail.title }}</h1><span>截止时间：{{ date(detail.deadline) }}</span></div><b class="status">{{ formation ? '组队中' : '小组已锁定' }}</b></header>
      <div class="content">
        <section class="requirements"><h2>作业要求</h2><p>{{ detail.description || '暂无详细作业说明' }}</p></section>
        <section v-if="detail.parts?.length" class="requirements"><h2>评价分支</h2><div v-for="part in detail.parts" :key="part.id" class="part"><span>{{ part.name }}</span><b>{{ Number(part.weight * 100).toFixed(0) }}%</b><small>{{ part.description || '暂无说明' }}</small></div></section>
        <section v-if="formation" class="formation"><h2>组队中</h2><p>加入小组后立即生效，组队期结束后小组自动锁定。</p><div class="join"><button class="primary" :disabled="working || detail.groupName" @click="createGroup">{{ detail.groupName ? '已加入小组' : '创建小组' }}</button><select v-model="selectedGroup" :disabled="working || detail.groupName"><option value="">请选择小组</option><option v-for="group in groups" :key="group.id" :value="group.groupNo" :disabled="group.memberCount >= group.maxMembers">{{ group.groupNo }}（{{ group.memberCount }}人）</option></select><button class="secondary" :disabled="working || !selectedGroup || detail.groupName" @click="joinGroup">加入小组</button></div></section>
        <section><h2>我的小组</h2><div v-if="detail.groupName" class="team"><strong>{{ detail.groupName }}</strong><label v-for="member in detail.members" :key="member.studentId"><span>{{ member.name }}（{{ member.studentNo }}）</span><input type="number" min="0" max="100" step="0.1" placeholder="贡献值 %" /></label><button v-if="formation" class="leave" @click="leaveGroup">取消，重新组队</button><em v-else>小组已锁定</em></div><el-empty v-else description="暂未加入小组"/></section>
        <StudentSubmissionPanel v-if="!formation" :assignment-id="route.params.assignmentId" :initial-content="detail.content" :initial-note="detail.submitNote" @submitted="load"/>
      </div>
    </section>
    <div v-else class="loading">正在加载…</div>
  </div>
</template>
<script setup>
import { computed,onMounted,ref } from 'vue';import { useRoute,useRouter } from 'vue-router';import { ElMessage } from 'element-plus';import StudentSubmissionPanel from '@/components/student/StudentSubmissionPanel.vue';import { createStudentGroup,getAssignment,getAssignmentGroups,joinStudentGroup,leaveStudentGroup } from '@/api/student';import { getErrorMessage } from '@/api/response'
const route=useRoute();const router=useRouter();const detail=ref(null);const groups=ref([]);const selectedGroup=ref('');const errorMessage=ref('');const working=ref(false);const formation=computed(()=>detail.value?.publishedAt&&Date.now()-new Date(detail.value.publishedAt).getTime()<172800000);const date=value=>value?new Date(value).toLocaleString('zh-CN'):'未设置';const load=async()=>{detail.value=await getAssignment(route.params.assignmentId);groups.value=await getAssignmentGroups(route.params.assignmentId)};const createGroup=async()=>{working.value=true;try{await createStudentGroup(route.params.assignmentId);await load();ElMessage.success('小组创建成功')}catch(e){errorMessage.value=getErrorMessage(e,'创建小组失败')}finally{working.value=false}};const joinGroup=async()=>{working.value=true;try{await joinStudentGroup(route.params.assignmentId,Number(selectedGroup.value));await load();ElMessage.success('加入小组成功')}catch(e){errorMessage.value=getErrorMessage(e,'加入小组失败')}finally{working.value=false}};const leaveGroup=async()=>{if(!confirm('确定退出当前小组并重新组队吗？'))return;try{await leaveStudentGroup(route.params.assignmentId);await load();ElMessage.success('已退出小组')}catch(e){errorMessage.value=getErrorMessage(e,'退出小组失败')}};onMounted(async()=>{try{await load()}catch(e){errorMessage.value=getErrorMessage(e,'作业详情加载失败')}})
</script>
<style scoped>.page{max-width:980px;margin:0 auto}.crumb{display:flex;gap:8px;margin-bottom:24px;color:#8795a6}.crumb button{border:0;background:none;color:inherit;cursor:pointer}.panel{overflow:hidden;border-radius:9px;background:#fff;box-shadow:0 3px 12px #263b5310}header{display:flex;justify-content:space-between;padding:26px;border-bottom:1px solid #edf1f4}header p{color:#6b9ed8;letter-spacing:1.5px;font-size:11px}h1{margin:8px 0;color:#263b53}.status{height:max-content;padding:6px 13px;border-radius:99px;color:#356798;background:#eaf2fa}.content{padding:26px}h2{color:#334155;font-size:17px}.requirements p,.formation p{color:#64748b;line-height:1.8}.part{display:grid;grid-template-columns:1fr auto;gap:5px;padding:12px;border-bottom:1px solid #edf1f4}.part b{color:#356798}.part small{grid-column:1/-1;color:#98a5b3}.formation{padding:18px;border:1px solid #d9e8f5;border-radius:8px;background:#f7fbff}.join{display:flex;gap:10px;margin-top:16px}.join select{min-width:180px;border:1px solid #dbe3ea;border-radius:6px}.primary,.secondary,.leave{padding:10px 17px;border:0;border-radius:6px;cursor:pointer}.primary{color:#fff;background:#356798}.secondary{color:#356798;background:#eaf2fa}.leave{color:#b42318;background:#fff5f5}.team{display:flex;flex-wrap:wrap;align-items:center;gap:10px}.team strong,.team span{padding:9px 13px;border-radius:6px;background:#f3f7fa;color:#52657a}.team strong{color:#356798;background:#eaf2fa}.error{padding:12px;color:#b42318;background:#fff5f5}.loading{text-align:center;padding:40px;color:#8795a6}@media(max-width:700px){.join{flex-direction:column}.join select{min-height:38px}}</style>
